themes.lightCss:
@plugin "daisyui/theme" {
  name: "sample-light";
  default: true;
  prefersdark: false;
  color-scheme: light;
  --color-base-100: oklch(100% 0 0);
  --color-base-200: oklch(97% 0.005 250);
  --color-base-300: oklch(93% 0.01 250);
  --color-base-content: oklch(22% 0.02 255);
  --color-primary: oklch(40% 0.13 159);
  --color-primary-content: oklch(99% 0 0);
  --color-secondary: oklch(34% 0.1 267);
  --color-secondary-content: oklch(99% 0 0);
  --color-accent: oklch(59% 0.13 48);
  --color-accent-content: oklch(99% 0 0);
  --color-neutral: oklch(28% 0.02 255);
  --color-neutral-content: oklch(98% 0 0);
  --color-info: oklch(70% 0.1 228);
  --color-info-content: oklch(17% 0.02 228);
  --color-success: oklch(70% 0.13 158);
  --color-success-content: oklch(17% 0.02 158);
  --color-warning: oklch(80% 0.12 90);
  --color-warning-content: oklch(18% 0.02 90);
  --color-error: oklch(67% 0.18 27);
  --color-error-content: oklch(98% 0 0);
  --radius-selector: 0.5rem;
  --radius-field: 0.5rem;
  --radius-box: 1rem;
  --size-selector: 0.1875rem;
  --size-field: 0.25rem;
  --border: 1px;
  --depth: 1;
  --noise: 0;
}

themes.darkCss:
@plugin "daisyui/theme" {
  name: "sample-dark";
  default: false;
  prefersdark: true;
  color-scheme: dark;
  --color-base-100: oklch(18% 0.02 256);
  --color-base-200: oklch(23% 0.02 256);
  --color-base-300: oklch(31% 0.02 256);
  --color-base-content: oklch(94% 0.01 255);
  --color-primary: oklch(75% 0.17 157);
  --color-primary-content: oklch(18% 0.02 155);
  --color-secondary: oklch(69% 0.15 266);
  --color-secondary-content: oklch(14% 0.02 266);
  --color-accent: oklch(70% 0.14 50);
  --color-accent-content: oklch(20% 0.02 45);
  --color-neutral: oklch(34% 0.02 256);
  --color-neutral-content: oklch(98% 0 0);
  --color-info: oklch(72% 0.1 230);
  --color-info-content: oklch(15% 0.02 230);
  --color-success: oklch(73% 0.13 155);
  --color-success-content: oklch(12% 0.02 150);
  --color-warning: oklch(83% 0.13 82);
  --color-warning-content: oklch(18% 0.02 80);
  --color-error: oklch(74% 0.17 27);
  --color-error-content: oklch(18% 0.02 27);
  --radius-selector: 0.5rem;
  --radius-field: 0.5rem;
  --radius-box: 1rem;
  --size-selector: 0.1875rem;
  --size-field: 0.25rem;
  --border: 1px;
  --depth: 1;
  --noise: 0;
}
